    GameChallenge(11),
    VoiceNote(12),
    MissedCall(13),
    IncomingCall(14);

    fun toWire(): Int = wire

    companion object {
        /** Unknown discriminants decode to [Unknown] so a new variant never breaks an old peer. */
        fun fromWire(value: Long): NotificationKind = when (value) {
            1L -> Message
            2L -> Mention
            3L -> Reply
            4L -> FriendRequest
            5L -> Gift
            6L -> LevelUp
            7L -> Achievement
            8L -> RoomInvite
            9L -> RoomAnnouncement
            10L -> Event
            11L -> GameChallenge
            12L -> VoiceNote
            13L -> MissedCall
            14L -> IncomingCall
            else -> Unknown
        }
    }
}

enum class RelationshipKind(val wire: Int) {
    Unknown(0),
    Friend(1),
    PendingOutgoing(2),
    PendingIncoming(3),
    Follow(4),
    Block(5),
    Favorite(6),
