/** Sent in RECONNECT_HINT / close frames so the client can pick the right recovery path */
enum class CloseReason(val wire: Int) {
    Unknown(0),
    ClientRequest(1),
    ServerShutdown(2),
    NodeDraining(3),
    SessionLagging(4),
    ResumeRequired(5),
    AuthExpired(6),
    Rebalance(7),
    ProtocolViolation(8);

    fun toWire(): Int = wire

    companion object {
        /** Unknown discriminants decode to [Unknown] so a new variant never breaks an old peer. */
        fun fromWire(value: Long): CloseReason = when (value) {
            1L -> ClientRequest
            2L -> ServerShutdown
            3L -> NodeDraining
            4L -> SessionLagging
            5L -> ResumeRequired
            6L -> AuthExpired
            7L -> Rebalance
            8L -> ProtocolViolation
            else -> Unknown
        }
    }
}

/** What an ML-DSA login challenge may be used for; mixed into the challenge payload so a challenge issued for one purpose cannot be answered for another */
enum class MlDsaPurpose(val wire: Int) {
    Unknown(0),
    /** Sign in as a registered device: identity + device signatures */
    Login(1),
    /** Register a new device under an existing identity */
    AddDevice(2),
    /** Approve an identity key rotation */
    Rotate(3);

    fun toWire(): Int = wire

    companion object {
        /** Unknown discriminants decode to [Unknown] so a new variant never breaks an old peer. */
        fun fromWire(value: Long): MlDsaPurpose = when (value) {
            1L -> Login
            2L -> AddDevice
            3L -> Rotate
            else -> Unknown
        }
    }
}

/** Who is connecting. Used for feature gating and abuse triage, never for tracking. */
data class ClientInfo(
    val platform: Platform,
    val appVersion: String,
    val osVersion: String? = null,
    val deviceModel: String? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.u32(platform.toWire())
        w.str(appVersion)
        var present = 0
        if (osVersion != null) present++
        if (deviceModel != null) present++
        w.u32(present)
        if (osVersion != null) {
            val value = osVersion
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (deviceModel != null) {
            val value = deviceModel
            w.optional(2) { w ->
                w.str(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): ClientInfo {
            r.enter()
            val platform = Platform.fromWire(r.u32())
            val appVersion = r.str()
            var osVersion: String? = null
            var deviceModel: String? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> osVersion = sub.str()
                    2L -> deviceModel = sub.str()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return ClientInfo(platform, appVersion, osVersion, deviceModel)
        }
    }
}

/** Resume an existing session instead of a full re-sync. */
data class ResumeRequest(
    val sessionId: Id,
    val lastFrameSeq: Long,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(sessionId)
        w.u64(lastFrameSeq)
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): ResumeRequest {
            r.enter()
            val sessionId = r.id()
            val lastFrameSeq = r.u64()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return ResumeRequest(sessionId, lastFrameSeq)
        }
    }
}

/** First frame on every connection. */
data class Hello(
    val protocolVersion: Long,
    val client: ClientInfo,
    /** Client feature bitmask; the session uses the intersection with the server's */
    val features: ULong,
    val locale: String,
    val bandwidthMode: BandwidthMode,
    /** Saves a round trip: authenticate inside HELLO */
    val accessToken: String? = null,
    val deviceId: Id? = null,
    val resume: ResumeRequest? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.u32(protocolVersion)
        client.encode(w)
        w.u64big(features)
        w.str(locale)
        w.u32(bandwidthMode.toWire())
        var present = 0
        if (accessToken != null) present++
        if (deviceId != null) present++
        if (resume != null) present++
        w.u32(present)
        if (accessToken != null) {
            val value = accessToken
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (deviceId != null) {
            val value = deviceId
            w.optional(2) { w ->
                w.id(value)
            }
        }
        if (resume != null) {
            val value = resume
            w.optional(3) { w ->
                value.encode(w)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): Hello {
            r.enter()
            val protocolVersion = r.u32()
            val client = ClientInfo.decode(r)
            val features = r.u64big()
            val locale = r.str()
            val bandwidthMode = BandwidthMode.fromWire(r.u32())
            var accessToken: String? = null
            var deviceId: Id? = null
            var resume: ResumeRequest? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> accessToken = sub.str()
                    2L -> deviceId = sub.id()
                    3L -> resume = ResumeRequest.decode(sub)
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return Hello(protocolVersion, client, features, locale, bandwidthMode, accessToken, deviceId, resume)
        }
    }
}

