            val maxBatchItems = r.u32()
            val maxSubscriptions = r.u32()
            val heartbeatMs = r.u32()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return Limits(maxFrameBytes, maxBatchItems, maxSubscriptions, heartbeatMs)
