data class Welcome(
    val sessionId: Id,
    val node: NodeInfo,
    val features: ULong,
    val serverTime: Long,
    val limits: Limits,
    val resumed: Boolean? = null,
    val resumeFromSeq: Long? = null,
    /** Present when HELLO carried a valid access token */
    val authenticatedUser: Id? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(sessionId)
        node.encode(w)
        w.u64big(features)
        w.timestamp(serverTime)
        limits.encode(w)
        var present = 0
        if (resumed != null) present++
        if (resumeFromSeq != null) present++
        if (authenticatedUser != null) present++
        w.u32(present)
        if (resumed != null) {
            val value = resumed
            w.optional(1) { w ->
                w.bool(value)
            }
        }
        if (resumeFromSeq != null) {
            val value = resumeFromSeq
            w.optional(2) { w ->
                w.u64(value)
            }
        }
        if (authenticatedUser != null) {
            val value = authenticatedUser
            w.optional(3) { w ->
                w.id(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): Welcome {
            r.enter()
            val sessionId = r.id()
            val node = NodeInfo.decode(r)
            val features = r.u64big()
            val serverTime = r.timestamp()
            val limits = Limits.decode(r)
            var resumed: Boolean? = null
            var resumeFromSeq: Long? = null
            var authenticatedUser: Id? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> resumed = sub.bool()
                    2L -> resumeFromSeq = sub.u64()
                    3L -> authenticatedUser = sub.id()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return Welcome(sessionId, node, features, serverTime, limits, resumed, resumeFromSeq, authenticatedUser)
        }
    }
}

data class Authenticate(
