data class UserProfile(
    val userId: Id,
    /** MGO-XXXXXXXX, immutable, shareable */
    val publicId: String,
    val username: String,
    val displayName: String,
    val avatarUrl: String? = null,
    val bio: String? = null,
    val country: String? = null,
    val language: String? = null,
    val level: Long? = null,
    val presence: PresenceState? = null,
    val badges: List<String>? = null,
    val verified: Boolean? = null,
    val customStatus: String? = null,
    /** The avatar media object; clients fetch a short-lived URL for it. */
    val avatarMediaId: Id? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(userId)
        w.str(publicId)
        w.str(username)
        w.str(displayName)
        var present = 0
        if (avatarUrl != null) present++
        if (bio != null) present++
        if (country != null) present++
        if (language != null) present++
        if (level != null) present++
        if (presence != null) present++
        if (badges != null) present++
        if (verified != null) present++
        if (customStatus != null) present++
        if (avatarMediaId != null) present++
        w.u32(present)
        if (avatarUrl != null) {
            val value = avatarUrl
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (bio != null) {
            val value = bio
            w.optional(2) { w ->
                w.str(value)
            }
        }
        if (country != null) {
            val value = country
            w.optional(3) { w ->
                w.str(value)
            }
        }
        if (language != null) {
            val value = language
            w.optional(4) { w ->
                w.str(value)
            }
        }
        if (level != null) {
            val value = level
            w.optional(5) { w ->
                w.u32(value)
            }
        }
        if (presence != null) {
            val value = presence
            w.optional(6) { w ->
                w.u32(value.toWire())
            }
        }
        if (badges != null) {
            val value = badges
            w.optional(7) { w ->
                w.listLen(value.size)
                for (item in value) { w.str(item) }
            }
        }
        if (verified != null) {
            val value = verified
            w.optional(8) { w ->
                w.bool(value)
            }
        }
        if (customStatus != null) {
            val value = customStatus
            w.optional(9) { w ->
                w.str(value)
            }
        }
        if (avatarMediaId != null) {
            val value = avatarMediaId
            w.optional(10) { w ->
                w.id(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): UserProfile {
            r.enter()
            val userId = r.id()
            val publicId = r.str()
            val username = r.str()
            val displayName = r.str()
            var avatarUrl: String? = null
            var bio: String? = null
            var country: String? = null
            var language: String? = null
            var level: Long? = null
            var presence: PresenceState? = null
            var badges: List<String>? = null
            var verified: Boolean? = null
            var customStatus: String? = null
            var avatarMediaId: Id? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> avatarUrl = sub.str()
                    2L -> bio = sub.str()
                    3L -> country = sub.str()
                    4L -> language = sub.str()
                    5L -> level = sub.u32()
                    6L -> presence = PresenceState.fromWire(sub.u32())
                    7L -> badges = run { val n = sub.listLen(); val acc = ArrayList<String>(n); for (i in 0 until n) acc.add(sub.str()); acc }
                    8L -> verified = sub.bool()
                    9L -> customStatus = sub.str()
                    10L -> avatarMediaId = sub.id()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return UserProfile(userId, publicId, username, displayName, avatarUrl, bio, country, language, level, presence, badges, verified, customStatus, avatarMediaId)
        }
    }
}

data class Authenticated(
    val userId: Id,
    val deviceId: Id,
    /** Capability bitmask for this session */
    val capabilities: ULong,
    val profile: UserProfile? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(userId)
        w.id(deviceId)
        w.u64big(capabilities)
        var present = 0
        if (profile != null) present++
        w.u32(present)
        if (profile != null) {
            val value = profile
            w.optional(1) { w ->
                value.encode(w)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): Authenticated {
            r.enter()
            val userId = r.id()
            val deviceId = r.id()
            val capabilities = r.u64big()
            var profile: UserProfile? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> profile = UserProfile.decode(sub)
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return Authenticated(userId, deviceId, capabilities, profile)
        }
    }
}

/** Carried with the ERROR flag on any opcode, or standalone. */
data class Error(
    val code: Long,
    /** Stable machine-readable symbol; clients localise from this, never from message */
    val symbol: String,
    /** Developer-facing detail. Never shown verbatim to users */
    val message: String? = null,
    val retryAfterMs: Long? = null,
    /** Offending field for validation errors */
    val field: String? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.u32(code)
        w.str(symbol)
        var present = 0
        if (message != null) present++
        if (retryAfterMs != null) present++
        if (field != null) present++
        w.u32(present)
        if (message != null) {
            val value = message
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (retryAfterMs != null) {
            val value = retryAfterMs
            w.optional(2) { w ->
                w.u32(value)
            }
        }
        if (field != null) {
            val value = field
            w.optional(3) { w ->
                w.str(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): Error {
            r.enter()
            val code = r.u32()
            val symbol = r.str()
            var message: String? = null
            var retryAfterMs: Long? = null
            var field: String? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> message = sub.str()
                    2L -> retryAfterMs = sub.u32()
                    3L -> field = sub.str()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return Error(code, symbol, message, retryAfterMs, field)
        }
    }
}

