        w.leave()
    }

    companion object {
        fun decode(r: Reader): ReconnectHint {
            r.enter()
            val reason = CloseReason.fromWire(r.u32())
            val afterMs = r.u32()
            var endpoint: String? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
