data class SubscribeRequest(
    val topics: List<Topic>,
) {
    fun encode(w: Writer) {
        w.enter()
        w.listLen(topics.size)
        for (item in topics) { item.encode(w) }
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): SubscribeRequest {
            r.enter()
            val topics = run { val n = r.listLen(); val acc = ArrayList<Topic>(n); for (i in 0 until n) acc.add(Topic.decode(r)); acc }
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
