/** Public halves only. The server never receives private key material. */
data class KeyPublish(
    val identityKey: ByteArray,
    val signedPrekeyId: Long,
    val signedPrekey: ByteArray,
    val signedPrekeySignature: ByteArray,
    val oneTimePrekeys: List<PrekeyEntry>,
) {
    fun encode(w: Writer) {
        w.enter()
        w.bytes(identityKey)
        w.u32(signedPrekeyId)
        w.bytes(signedPrekey)
        w.bytes(signedPrekeySignature)
        w.listLen(oneTimePrekeys.size)
        for (item in oneTimePrekeys) { item.encode(w) }
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): KeyPublish {
            r.enter()
            val identityKey = r.bytes()
            val signedPrekeyId = r.u32()
            val signedPrekey = r.bytes()
            val signedPrekeySignature = r.bytes()
            val oneTimePrekeys = run { val n = r.listLen(); val acc = ArrayList<PrekeyEntry>(n); for (i in 0 until n) acc.add(PrekeyEntry.decode(r)); acc }
            val optionalCount = r.u32()
