        if (maxMembers != null) present++
        w.u32(present)
        if (topic != null) {
            val value = topic
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (description != null) {
            val value = description
            w.optional(2) { w ->
                w.str(value)
            }
        }
