        if (language != null) {
            val value = language
            w.optional(5) { w ->
                w.str(value)
            }
        }
        if (country != null) {
            val value = country
            w.optional(6) { w ->
                w.str(value)
            }
        }
        if (verified != null) {
            val value = verified
            w.optional(7) { w ->
                w.bool(value)
            }
        }
        if (myRole != null) {
            val value = myRole
            w.optional(8) { w ->
                w.u32(value.toWire())
            }
        }
        if (slowModeMs != null) {
            val value = slowModeMs
            w.optional(9) { w ->
                w.u32(value)
            }
        }
        if (maxMembers != null) {
            val value = maxMembers
            w.optional(10) { w ->
                w.u32(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): RoomSummary {
            r.enter()
            val roomId = r.id()
            val publicId = r.str()
            val kind = RoomKind.fromWire(r.u32())
            val name = r.str()
            val memberCount = r.u32()
            val onlineCount = r.u32()
            var topic: String? = null
            var description: String? = null
            var avatarUrl: String? = null
            var category: String? = null
            var language: String? = null
            var country: String? = null
            var verified: Boolean? = null
            var myRole: RoomRole? = null
            var slowModeMs: Long? = null
            var maxMembers: Long? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> topic = sub.str()
                    2L -> description = sub.str()
                    3L -> avatarUrl = sub.str()
                    4L -> category = sub.str()
                    5L -> language = sub.str()
                    6L -> country = sub.str()
                    7L -> verified = sub.bool()
                    8L -> myRole = RoomRole.fromWire(sub.u32())
                    9L -> slowModeMs = sub.u32()
                    10L -> maxMembers = sub.u32()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
