/** Aggregate quality numbers; Droppable; never call content. */
data class CallStats(
    val callId: Id,
    val setupMs: Long? = null,
    val rttMs: Long? = null,
    /** Per-10000. */
    val packetLoss: Long? = null,
    val jitterMs: Long? = null,
    val usedTurn: Boolean? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(callId)
        var present = 0
        if (setupMs != null) present++
        if (rttMs != null) present++
        if (packetLoss != null) present++
        if (jitterMs != null) present++
        if (usedTurn != null) present++
        w.u32(present)
        if (setupMs != null) {
            val value = setupMs
            w.optional(1) { w ->
                w.u32(value)
            }
        }
        if (rttMs != null) {
            val value = rttMs
            w.optional(2) { w ->
                w.u32(value)
            }
        }
        if (packetLoss != null) {
            val value = packetLoss
            w.optional(3) { w ->
                w.u32(value)
            }
        }
        if (jitterMs != null) {
            val value = jitterMs
            w.optional(4) { w ->
                w.u32(value)
            }
        }
        if (usedTurn != null) {
            val value = usedTurn
            w.optional(5) { w ->
                w.bool(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): CallStats {
            r.enter()
            val callId = r.id()
            var setupMs: Long? = null
            var rttMs: Long? = null
            var packetLoss: Long? = null
            var jitterMs: Long? = null
            var usedTurn: Boolean? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> setupMs = sub.u32()
                    2L -> rttMs = sub.u32()
                    3L -> packetLoss = sub.u32()
                    4L -> jitterMs = sub.u32()
                    5L -> usedTurn = sub.bool()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return CallStats(callId, setupMs, rttMs, packetLoss, jitterMs, usedTurn)
        }
    }
}

/** One TURN relay with short-lived credentials. */
data class TurnServer(
    val url: String,
    val username: String,
    val credential: String,
    val ttlSeconds: Long,
    val region: String,
) {
    fun encode(w: Writer) {
        w.enter()
        w.str(url)
        w.str(username)
        w.str(credential)
        w.u32(ttlSeconds)
        w.str(region)
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): TurnServer {
            r.enter()
            val url = r.str()
            val username = r.str()
            val credential = r.str()
            val ttlSeconds = r.u32()
            val region = r.str()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return TurnServer(url, username, credential, ttlSeconds, region)
        }
    }
}

/** Requests TURN credentials for a call. */
data class CallTurnFetch(
    val callId: Id,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(callId)
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): CallTurnFetch {
            r.enter()
            val callId = r.id()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return CallTurnFetch(callId)
        }
    }
}

/** TURN servers with temporary credentials. */
data class CallTurnResponse(
    val servers: List<TurnServer>,
) {
    fun encode(w: Writer) {
        w.enter()
        w.listLen(servers.size)
        for (item in servers) { item.encode(w) }
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): CallTurnResponse {
            r.enter()
            val servers = run { val n = r.listLen(); val acc = ArrayList<TurnServer>(n); for (i in 0 until n) acc.add(TurnServer.decode(r)); acc }
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return CallTurnResponse(servers)
        }
    }
}

/** Identifies one call. */
data class CallId(
    val callId: Id,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(callId)
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): CallId {
            r.enter()
            val callId = r.id()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return CallId(callId)
        }
    }
}

/** The bytes an ML-DSA login ceremony signs: issued over REST, MSE-encoded by the server, signed by the client exactly as received so no port re-encodes it differently. Single use, short lived, bound to one account, device and purpose. */
data class MlDsaChallenge(
    val protocolVersion: Long,
    val purpose: MlDsaPurpose,
    /** The account the challenge authenticates */
    val accountId: Id,
    /** The device the challenge is bound to; for add-device, the new device */
    val deviceId: Id,
    /** Server-side handle; single use — the first answer consumes it */
    val challengeId: Id,
    /** 32 bytes from the server CSPRNG; never derived from anything the client controls */
    val nonce: ByteArray,
    val issuedAt: Long,
    /** Five minutes after issuance */
    val expiresAt: Long,
    /** Deployment identity, so a challenge from one deployment cannot be answered at another */
    val serverRegion: String,
) {
    fun encode(w: Writer) {
        w.enter()
        w.u32(protocolVersion)
        w.u32(purpose.toWire())
        w.id(accountId)
        w.id(deviceId)
        w.id(challengeId)
        w.bytes(nonce)
        w.timestamp(issuedAt)
        w.timestamp(expiresAt)
        w.str(serverRegion)
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): MlDsaChallenge {
            r.enter()
            val protocolVersion = r.u32()
            val purpose = MlDsaPurpose.fromWire(r.u32())
            val accountId = r.id()
            val deviceId = r.id()
            val challengeId = r.id()
            val nonce = r.bytes()
            val issuedAt = r.timestamp()
            val expiresAt = r.timestamp()
            val serverRegion = r.str()
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return MlDsaChallenge(protocolVersion, purpose, accountId, deviceId, challengeId, nonce, issuedAt, expiresAt, serverRegion)
        }
    }
}

/** Delivery class, deciding what happens when a session queue is full. */
enum class DeliveryClass { Critical, Coalescable, Droppable }
/** Minimum session state an opcode requires. */
enum class AuthLevel { None, User, Bot, Server }
/** Direction an opcode may legally travel. */
enum class Direction { ClientToServer, ServerToClient, Both }

